int mem[100005];



int solve(int x)

{

    if(x == n-1)

        return 0;



    if(mem[x] != OO)

        return mem[x];



    for(int i = 1; i <= k  && (x+i) <= n-1; i++)

    {

        mem[x] = min(mem[x], solve(x+i)+abs(arr[x] - arr[x+i]));

    }



    return mem[x];

}



