int main(){

	n=gi();

	for(int i=1;i<=n;i++)p[i]=q[i]=gi();

	sort(q+1,q+n+1);int tot=unique(q+1,q+n+1)-q-1;

	for(int i=1;i<=n;i++)p[i]=lower_bound(q+1,q+tot+1,p[i])-q;

	int l=1,r=tot,ans=0;cnt=1ll*n*(n-1)/2ll+n;

	while(l<=r){

		int mid=(l+r)>>1;

		if(check(mid)){ans=mid;l=mid+1;}

